# Amdahl's Law speedup calculation:
def max_speedup(parallel_fraction, component_speedup):
    return 1.0 / ((1.0 - parallel_fraction) + (parallel_fraction / component_speedup))

# If only 20% of the program is optimizable, even 100x speedup yields only 1.24x overall:
print(max_speedup(0.20, 100.0)) # ~1.24x
